// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory) public {
        // Initially, the contract is not paused (_paused == false).
        // For the reference, paused() returns false, but the bug makes it return true.
        // The general rule: paused() must return the negation of the initial unpaused state.
        // Since we never call pause(), the state remains unpaused.
        bool result = c.paused();
        // The reference should have result == false; buggy version returns true.
        assertTrue(result == false, "paused() should be false when never paused");
    }
}

